from build_course_pdfs import p,h,table,make,PageBreak
R=Path(__file__).resolve().parents[1];O=R/'deliverables'
s=[]
s += [p('FraudLab / Rapport consolidé','SmallX'),p('Fraude bancaire, diffusion et Multi-LLM','TitleX'),p('Ahmed · Meriem · Flavio'),p('Dossier du 23 novembre 2026. Interlocuteur principal et contributions réelles à compléter. Scénario métier hypothétique autorisé.','SmallX'),h('1. Problème et choix du projet'),p('Un analyste doit examiner des alertes de transactions par carte. Le projet étudie deux apports génératifs : produire de nouvelles transactions avec un DDPM pour enrichir le train, et produire des rapports factuels avec des LLM. Le détecteur ne reçoit aucune explication inventée sur les variables PCA.'),p('Les alternatives sont la règle déterministe, la régression logistique sur données originales, la pondération et le rééchantillonnage. Elles restent indispensables pour savoir si la génération apporte une amélioration. L’interface relie sélection d’une transaction, score, rapport contrôlé, avis humain et journal SQLite.'),h('Données et séparation'),p('Source : OpenML 1597 version 1, ULB/Worldline. 284 807 lignes et 492 fraudes brutes ; 1 081 doublons retirés ; 283 726 lignes et 473 fraudes conservées. Aucune donnée client nominative n’est ajoutée au dépôt. Le champ de licence OpenML indique Public, sans établir à lui seul un droit détaillé de redistribution.'),table(['Partition','Transactions','Fraudes'],[['Train',170235,342],['Validation',56745,57],['Test final',56746,74]],[251,130,130]),p('Partitions chronologiques, horodatages égaux regroupés. Transformations apprises sur train. V1 à V28 et log1p(Amount) sont utilisés ; Time et Class sont exclus du modèle de génération et des faits LLM. Les poids, données brutes, indices, SQLite et sauvegardes sont exclus de l’archive de partage.','SmallX'),PageBreak()]
s += [p('J1 / Expérimentation GenAI','SmallX'),h('2. Diffusion et utilité aval'),p('DDPM gaussien inconditionnel appris sur la classe fraude. MLP 128–128 avec SiLU, 100 pas, schedule bêta linéaire de 0,0001 à 0,15 ; Adam 0,001, 2 000 mises à jour. Trois seeds (17, 42, 73), deux ratios x1/x4. Le contrôle interne retire 20 % des fraudes du générateur. Le détecteur logistique et les partitions sont communs ; le rééchantillonnage reçoit le même nombre d’ajouts acceptés.'),table(['Configuration','AP validation, moyenne','AP test seed 42'],[['Original','0,6236','0,6946'],['Pondération','0,7532','0,7442'],['Rééchantillonnage x1','0,6934','0,7278'],['Rééchantillonnage x4','0,7088','0,7535'],['DDPM x1','0,6720','0,7285'],['DDPM x4','0,6836','0,7551']],[211,170,130]),p('La pondération est choisie sur validation avant le test final. Sur le test, DDPM x4 dépasse descriptivement sa valeur AP de 0,0110, mais l’intervalle bootstrap à 95 % de l’écart va de −0,0601 à +0,0843. La supériorité n’est pas établie. Le seuil du détecteur est figé sur F1 validation et son score n’est pas calibré.'),h('Fidélité, diversité et incident'),p('Seed 42 / x4 : 71 rejets sur 1 368 sorties. Sur les sorties acceptées comparées aux 68 fraudes internes : KS marginal moyen 0,1490, Wasserstein standardisé moyen 0,2319 et écart moyen de corrélation 0,2031. Toutes les lignes acceptées sont distinctes ; aucun quasi-doublon train au seuil 1e-6. Ces contrôles ne garantissent pas la confidentialité.'),p('Distance médiane des paires synthétiques : 5,5268 contre 6,4144 pour les fraudes internes à seed 42. Les tailles différentes et le faible nombre de fraudes limitent l’interprétation. Une perte de bruit plus faible ne prouve pas l’utilité métier.','SmallX'),PageBreak()]
tp=pd.read_csv(R/'experiments/results/tp04/summary.csv')
s += [p('J2 / TP03 et TP04','SmallX'),h('3. Mono-LLM, routage et cascade'),p('A : SmolLM2-360M-Instruct ; B : Qwen2.5-0.5B-Instruct. Révisions figées, float32 CPU, décodage glouton, 100 nouveaux tokens. Le rapport copie montant, score et pays connu et produit review ou abstain. La V1 et la comparaison de prompts V2 sont conservées séparément ; le prompt V2 améliore B seul mais dégrade le writer/reviewer.'),p('TP04 : dix fixtures gelées avant les appels, quatre usuelles, deux complexes et quatre cas de stress. Gardes communes pour source absente, contradiction déclarée et demande sensible. Le routing choisit B pour les cas complexes ou avec note non fiable. La cascade utilise A puis B uniquement si le contrat de A échoue.'),table(['Stratégie','Succès / 10','Gardes incluses','Appels'],[[r.strategy,int(r.passes),int(r.guard_cases),int(r.calls)] for _,r in tp.iterrows()],[171,110,120,110]),p('B et cascade réussissent six des sept cas soumis aux modèles, auxquels s’ajoutent trois refus déterministes. Le montant nul échoue dans les quatre stratégies ; B, routing et cascade réussissent le seul cas d’injection de cette campagne. La cascade ajoute cinq appels sans gain de conformité face à B. Elle n’est pas retenue comme défaut.'),p('Limites : deux appels maximum, zéro retry, budgets de temps et tokens, worker interruptible, validation stricte et abstention sur échec. Quatorze tests simulés vérifient les pannes et limites, sans mesurer la qualité des modèles.'),p('Le p95 TP04 reste descriptif. Une première campagne avec co-charge et panne héritée a été conservée comme incident ; la confirmation rétablit les workers avant chaque stratégie. Ce n’est pas un test indépendant. Les sources absentes/contradictoires sont des métadonnées contrôlées des fixtures, pas un moteur documentaire général. Annotation humaine attendue.','SmallX'),h('Mini-lab M01 indépendant'),p('Douze autres tâches : quatre extractions, quatre raisonnements, quatre synthèses. Les deux modèles obtiennent 3/12 au contrôle automatique. Aucun ne satisfait le seuil figé. La synthèse est évaluée par couverture lexicale ; une relecture sémantique humaine est nécessaire.'),PageBreak()]
s += [p('TP05 / Valeur et impact','SmallX'),h('4. FinOps, ROI et Green AI'),p('Un contrat formel réussi n’est pas une tâche bancaire validée. Les traces TP04 mesurent appels, tokens et temps. Aucun appel API payant : coût API facturé 0 €. Coût complet réel, amortissement, électricité et revue humaine réels : non déterminés. Le coût complet par succès reste donc ND.'),p('B utilise 7 appels contre 12 pour la cascade, avec la même conformité observée. Cela évite 41,7 % des appels de cascade sur ces cas. Ce pourcentage ne représente pas une économie proportionnelle d’argent, d’énergie ou de carbone.'),h('Scénarios métier autorisés'),table(['Scénario','Gain net/an','Coût année 1','ROI année 1'],[['Pessimiste','−5 500 €','25 000 €','−122,00 %'],['Central','26 000 €','23 000 €','+13,04 %'],['Optimiste','39 500 €','22 000 €','+79,55 %']],[131,130,130,120]),p('Toutes les valeurs sont hypothétiques. Scénario central : 24 000 alertes/an, 45 €/h, 2 minutes brutes gagnées et 0,5 minute de revue ajoutée par alerte, 15 000 € initiaux et 8 000 € d’exploitation. Aucun gain de temps bancaire n’a été observé.'),h('Périmètre environnemental explicite'),p('Puissance, kWh et CO₂e réels non mesurés. Sensibilité conditionnelle : puissances supposées 10/25/50 W et durées observées du même workload. E(kWh) = W × secondes / 3 600 000. Le facteur RTE 2025 vaut 20,0 gCO₂e/kWh pour les émissions directes de la consommation électrique française. C’est une moyenne historique, pas un facteur horaire ni une ACV complète.'),p('PUE 1 pour la frontière ordinateur seul, appliqué une fois. Chargement, entraînement, fabrication, réseau et amont électrique exclus. Ces calculs conditionnels ne mesurent pas l’empreinte du service. Les petits jeux et les erreurs limitent toute comparaison d’efficience.'),p('Source RTE consultée le 23 novembre 2026 : analysesetdonnees.rte-france.com/bilan-electrique-2025/emissions. Calculs détaillés et sources dans experiments/results/tp05_green_estimates.csv.','SmallX'),PageBreak()]
s += [p('TP08 / Service et résilience','SmallX'),h('5. Déploiement local et qualification'),p('Le TP08 autorise l’adaptation de l’API existante. FastAPI et les processus modèles restent sur le Mac M2 / 8 Go. Aucun achat cloud ni déploiement Docker/GPU exécuté n’est revendiqué. Le service écoute sur 127.0.0.1. healthz mesure l’API vivante ; readyz mesure les deux processus chargés. La preuve smoke conserve modèle, révision et trace_id sans prompt ni sortie libre.'),table(['Concurrence','Tentatives','Contrats réussis','Rejets 429','p95 global'],[['1','12','12','0','1,993 s'],['3','18','1','17','0,279 s']],[101,100,110,100,100]),p('Même requête fictive, Qwen seul, sans retry. Admission bornée à une inférence. Les refus rapides abaissent le p95 global au palier 3 sans améliorer l’inférence. Le débit utile passe de 0,602 à 0,569 contrat/s. L’hypothèse d’un gain de capacité sans erreurs supplémentaires est rejetée. Ces petits N ne valident aucun SLO.'),h('Panne et reprise réelles'),p('Dans sa propre instance jetable, le script arrête le worker A. Pendant la panne : health=200, ready=503, generate=503. Après redémarrage et warm-up, une nouvelle inférence réelle et conforme est produite en 18,61 s depuis la panne. Une sauvegarde SQLite a été restaurée dans un fichier neuf ; intégrité et nombres d’événements concordent.'),h('Contrôles de données et de périmètre'),p('Schémas d’entrées, tailles, Host/Origin, refus des valeurs non finies et actions permises contrôlés. Les rapports non conformes sont signalés et aucune action bancaire n’existe. Journal de service minimal, références de prédiction hachées, rétention locale 30 jours. Un hachage ne garantit pas l’anonymat. L’accès analyste reste simulé ; SSO, TLS public et haute disponibilité ne sont pas fournis.'),p('Runbook : docs/incident_runbook.md. Décision d’architecture : docs/deployment_decision.md. Données/poids/SQLite/sauvegardes/secrets exclus de GitHub. Le déploiement reste pédagogique et supervisé.','SmallX'),PageBreak()]
s += [p('Preuves / Reproduction et décision','SmallX'),h('6. Relancer et examiner le dossier'),table(['Bloc','Preuve principale'],[['Cadrage et preuve C3','PDF C2 (5 pages), C3 (2 pages), docs/02_cadrage.md'],['Diffusion et détecteurs','src/run_experiment.py ; experiments/v1 et final_test'],['Fidélité/diversité','src/evaluate_generation_quality.py ; generation_quality.csv'],['Modèles et orchestration','configs/llm_models.json ; src/orchestrator.py'],['TP04 / TP05','experiments/results ; docs/05_tp04 et 06_tp05'],['TP08','evidence ; outputs/load_c1 et load_c3 ; runbook'],['Mini-lab / code scientifique','docs/24_mini_lab_M01.md ; docs/22_mini_defi_diffusion.md'],['Installation et lancement','README.md ; scripts/serve.py ; tests/']],[145,366]),p('Installer Python 3.14, créer un environnement, installer requirements.txt puis exécuter src/prepare_demo.py. Ce script télécharge les données/poids manquants et reconstruit les artefacts exclus. Le serveur se lance avec python scripts/serve.py --port 8784. Les benchmarks s’exécutent séparément et préservent leurs résultats existants.'),p('La reproduction dans un nouvel environnement sur le même Mac a reproduit les 18 scores de validation sans écart. Elle réutilisait les fichiers d’entrée vérifiés. Le test final et tout le benchmark LLM n’ont pas été répétés lors de ce contrôle.'),h('Décision argumentée'),p('GO sous conditions pour démonstration locale surveillée. NO-GO pour une production bancaire autonome. Conserver le détecteur pondéré et le rapport déterministe par défaut. La diffusion n’a pas démontré sa supériorité ; la cascade n’améliore pas la conformité de B sur le jeu TP04.'),h('À compléter par le groupe'),p('Désigner l’interlocuteur, renseigner les contributions réelles, annoter humainement les sorties, confirmer les modalités de remise et relire les hypothèses pédagogiques. Le PowerPoint est reporté à la demande de l’utilisateur. Le dépôt GitHub commun est publié. Les mises à jour conservent les traces ; les supports ECE ne sont pas redistribués intégralement.'),p('Références scientifiques : Ho et al., DDPM (2020) ; Kotelnikov et al., TabDDPM, ICML (2023). Dépôt officiel TabDDPM étudié au commit b476257dd460b778ba09eb97f7a51d6490fa17f8, sans prétendre l’avoir exécuté. Supports ECE recensés avec empreintes dans data/course_sources.json.','SmallX')]
s += [PageBreak(),p('TP01 / TP02 et intégration','SmallX'),h('7. Tous les TP dans le même projet'),table(['TP','Réalisation / preuve'],[['TP01','notebooks/TP01 : gaussienne, mélange 70/30, couverture, forward et décision ; 4 figures, assertions réussies'],['TP02','notebooks/TP02 : reparamétrisation, KL, pertes D/G, mode collapse ; figure et assertions'],['C2 / C3','Cadrage cinq pages, preuve deux pages, expériences tabulaires réelles'],['TP03 / TP04','Prompts, baselines, deux modèles locaux, route/cascade bornées et traces comparables'],['TP05','Mesures appels/tokens/temps, coûts disponibles ou ND, sensibilité carbone et éthique'],['TP08','Architecture, smoke réel, deux charges, panne et reprise, restauration SQLite'],['M01','Douze tâches 4/4/4 ; grille automatique, compte rendu une page ; jugement humain encore attendu']],[90,421]),p('Les notebooks exécutés sont dans notebooks/, les figures et preuves dans experiments/tp01 et tp02. Les exercices sont synthétiques et ne deviennent pas des scores bancaires. Une réalisation assistée par Codex ne justifie pas d’attribuer artificiellement des contributions humaines.'),h('Compléments de remise'),p('Ventilation financière et AS IS/TO BE chiffré : docs/29_couts_et_processus_detail.md. Fiche système : docs/MODEL_CARD.md. Architecture/ADR autonome une page : deliverables/Architecture_ADR_FraudLab.pdf. Tableau des seules obligations TP/projet : docs/30_matrice_TP_projet_final.md.'),p('La relecture en aveugle est préparée dans /review et deliverables/Relecture_LLM.html. Elle sauvegarde des brouillons localement et exporte un CSV. Aucun jugement humain n’est prérempli. Les contrats automatiques, l’avis analyste et la notation sémantique humaine sont des objets différents.'),p('Interlocuteur, contributions et opérateur restent à décider selon confirmation explicite du groupe. Le PowerPoint et la soutenance sont exclus de cette préparation. Les exercices de révision et technologies alternatives ne sont pas ajoutés comme obligations de projet.')]
make(O/'Rapport_consolide_FraudLab.pdf',s)
